    superclasses_to_remove = set()
    for i, cls in enumerate(cls_list):
        if not isinstance(cls, type):
            continue
        for j, other in enumerate(cls_list):
            if i == j or not isinstance(other, type):
                continue
            try:
                if issubclass(other, cls):
                    superclasses_to_remove.add(cls)
                    break
            except TypeError:
                # ignore if either is not a class; should not occur after isinstance
                continue

    # build the ordered minimal list, removing duplicates
    seen = set()
    minimal = []
    for cls in cls_list:
        if not isinstance(cls, type):
            continue
        if cls in superclasses_to_remove:
            # this class is a superclass of some other; skip
            continue
        if cls not in seen:
            minimal.append(cls)
            seen.add(cls)

    return minimal

